import type { Project, ProjectRole } from '@/entities/project/types'

type Props = {
  project: Project
  onClick?: () => void
}

const ROLE_LABEL: Record<ProjectRole, string> = {
  owner: 'Owner',
  admin: 'Admin',
  member: 'Member',
  viewer: 'Viewer',
  collaborator: 'Collaborator',
}

const GRADIENTS = [
  'from-violet-400 via-fuchsia-400 to-emerald-400',
  'from-sky-400 via-cyan-400 to-emerald-300',
  'from-amber-300 via-orange-400 to-rose-400',
  'from-emerald-400 via-teal-400 to-sky-400',
  'from-indigo-400 via-purple-400 to-pink-400',
  'from-lime-300 via-emerald-400 to-teal-500',
]

function pickGradient(seed: string): string {
  let h = 0
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0
  return GRADIENTS[h % GRADIENTS.length]
}

export function ProjectCard({ project, onClick }: Props) {
  const role = project.roleForCurrentUser ?? 'collaborator'
  const gradient = pickGradient(project.color ?? project.id)

  return (
    <button
      onClick={onClick}
      className="group w-full text-left bg-card rounded-lg border border-border overflow-hidden hover:shadow-card hover:border-foreground/20 transition-all"
    >
      <div
        className={`relative aspect-[16/9] w-full bg-gradient-to-br ${gradient}`}
        style={project.color ? { backgroundImage: `linear-gradient(135deg, ${project.color}, hsl(var(--primary)))` } : undefined}
      />
      <div className="p-4">
        <h3 className="font-semibold text-base text-foreground truncate">{project.title}</h3>
        <div className="mt-2">
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-pill text-xs border border-border bg-muted text-muted-foreground">
            {ROLE_LABEL[role]}
          </span>
        </div>
        {project.description && (
          <p className="mt-3 text-sm text-muted-foreground line-clamp-2 leading-relaxed">
            {project.description}
          </p>
        )}
      </div>
    </button>
  )
}
